final class ControladorCategorias extends ControladorCatalogosAdmin
{
    public function index(): array { $this->autorizar('categorias.gestionar');$f=['q'=>mb_substr(trim((string)($_GET['q']??'')),0,100),'estado'=>in_array((string)($_GET['estado']??''),['0','1'],true)?(string)$_GET['estado']:''];return ['filtros'=>$f,'listado'=>ModeloCatalogosAdmin::categorias($f),'estadisticas'=>ModeloCatalogosAdmin::resumenCategorias(),'padres'=>ModeloCatalogosAdmin::padres()]; }
